,"source_metadata":{}},{"key":"i_turnin","speaker_external_id":"mira_stonecarver","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro1_turnin","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro1_wake","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro2_bruno","speaker_external_id":"bruno_gardener","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro2_mira","speaker_external_id":"mira_stonecarver","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro2_noa","speaker_external_id":"noa","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro2_pip","speaker_external_id":"pip_bellringer","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro2_turnin","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro3_story","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"intro3_turnin","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"j_lesson","speaker_external_id":"bruno_gardener","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"j_turnin","speaker_external_id":"bruno_gardener","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"k_lesson","speaker_external_id":"pip_bellringer","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"k_turnin","speaker_external_id":"pip_bellringer","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"l_lesson","speaker_external_id":"noa","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"l_turnin","speaker_external_id":"noa","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"m_lesson","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"m_turnin","speaker_external_id":"grandpa_tobias","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"n_lesson","speaker_external_id":"bruno_gardener","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}},{"key":"n_turnin","speaker_external_id":"bruno_gardener","source_path":"_registry\\dialogues\\abc_valley.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"a_lesson","locale":"he","line_order":0,"content":"לפני שאתה יוצא, תסתכל על ההר שלנו. שני צדדים שנפגשים בפסגה, ושביל באמצע. ככה נראית A.","line_format":"plain_text"},{"dialogue_key":"a_turnin","locale":"he","line_order":0,"content":"כל הרסיסים! וניצחת את המימיק? טוב, הוא היה קטן. אבל כשהייתי צעיר, הייתי בורח גם מקטן.","line_format":"plain_text"},{"dialogue_key":"b_lesson","locale":"he","line_order":0,"content":"אתה יודע איזו אות אני הכי אוהב? B. היא נראית כמו אני אחרי ארוחה: קו ישר ושתי בטנים!","line_format":"plain_text"},{"dialogue_key":"b_turnin","locale":"he","line_order":0,"content":"ראית את הגבעול? עד השמיים! אף פעם לא גידלתי משהו כזה!","line_format":"plain_text"},{"dialogue_key":"c_lesson","locale":"he","line_order":0,"content":"שמעת? \"ק... ק...\". זה מגיע מהמערה.","line_format":"plain_text"},{"dialogue_key":"c_turnin","locale":"he","line_order":0,"content":"עשינו את זה! הייתי בפנים! ממש בפנים!","line_format":"plain_text"},{"dialogue_key":"d_lesson","locale":"he","line_order":0,"content":"סבא שלי קבר ליד הבריכה תוף זהב, והמפה שלו סימנה אותו באיקס. אבל הקוסם פיזר בלילה עוד המון איקסים!","line_format":"plain_text"},{"dialogue_key":"d_turnin","locale":"he","line_order":0,"content":"התוף של סבא שלי! יודע כמה שנים חיפשתי אותו?","line_format":"plain_text"},{"dialogue_key":"e_lesson","locale":"he","line_order":0,"content":"הרוח של הקוסם פיזרה את כל הביצים שלי בעמק! אם הן לא יבקעו בחום של הלול, האפרוחים יתקררו.","line_format":"plain_text"},{"dialogue_key":"e_turnin","locale":"he","line_order":0,"content":"כל האפרוחים! תראה איך הם הולכים אחריך בשורה, כאילו אתה אמא שלהם.","line_format":"plain_text"},{"dialogue_key":"f_lesson","locale":"he","line_order":0,"content":"ראית? האבנים המרחפות נופלות עם שובל זהב. הן חלקים של אבן העמידה הגדולה!","line_format":"plain_text"},{"dialogue_key":"f_turnin","locale":"he","line_order":0,"content":"תן לי להרגיש... הקו הזה, ועוד אחד, ועוד אחד. F.","line_format":"plain_text"},{"dialogue_key":"fun1_alarm","locale":"he","line_order":0,"content":"שמעת את הרעש הזה? משהו מגיע מהקניון!","line_format":"plain_text"},{"dialogue_key":"fun1_turnin","locale":"he","line_order":0,"content":"הם ברחו! ראית איך רצו?","line_format":"plain_text"},{"dialogue_key":"fun2_bet","locale":"he","line_order":0,"content":"תגיד, אתה חושב שאתה יכול לטפס עד הרכס? עד האותיות עצמן?","line_format":"plain_text"},{"dialogue_key":"fun2_turnin","locale":"he","line_order":0,"content":"טוב, טוב, הגעת ראשון. בפעם הבאה אני מנצחת.","line_format":"plain_text"},{"dialogue_key":"fun3_stones","locale":"he","line_order":0,"content":"הרגשתי את האבנים המרחפות. הן יציבות עכשיו. הן יכולות להחזיק ילד!","line_format":"plain_text"},{"dialogue_key":"fun3_turnin","locale":"he","line_order":0,"content":"ידעתי שהאבנים יחזיקו. הרגשתי את זה.","line_format":"plain_text"},{"dialogue_key":"g_lesson","locale":"he","line_order":0,"content":"סבא טוביאס, מה הסימן על העץ?","line_format":"plain_text"},{"dialogue_key":"g_turnin","locale":"he","line_order":0,"content":"ענק! היה ענק בכיכר שלנו!","line_format":"plain_text"},{"dialogue_key":"h_lesson","locale":"he","line_order":0,"content":"תסתכל על המפל! המים זורמים למעלה! והבריכה מלאה אותיות מבולבלות.","line_format":"plain_text"},{"dialogue_key":"h_turnin","locale":"he","line_order":0,"content":"המים חזרו לרדת! אני כל כך רטובה.","line_format":"plain_text"},{"dialogue_key":"hw1_letters","locale":"he","line_order":0,"content":"בוקר טוב! הגיעו ארבעה מכתבים, אחד לכל אות שהדלקת.","line_format":"plain_text"},{"dialogue_key":"hw1_turnin","locale":"he","line_order":0,"content":"כל המכתבים הגיעו? A, B, C, D... אתה כבר יודע ארבע אותיות!","line_format":"plain_text"},{"dialogue_key":"hw2_open","locale":"he","line_order":0,"content":"ברוך הבא לדוכן של ברונו! הכפר מזמין, ואנחנו מוכרים.","line_format":"plain_text"},{"dialogue_key":"hw2_turnin","locale":"he","line_order":0,"content":"כל ההזמנות נמסרו! אתה המוכר הכי טוב שהיה לי. בעצם, הראשון.","line_format":"plain_text"},{"dialogue_key":"hw3_plan","locale":"he","line_order":0,"content":"שמעת? לפעמון חזרו ארבעה צלילים! תליתי במגדל ארבעה פעמונים קטנים: I, J, K, L.","line_format":"plain_text"},{"dialogue_key":"hw3_turnin","locale":"he","line_order":0,"content":"שמעת את הכפר מוחא כפיים? זה בשבילנו!","line_format":"plain_text"},{"dialogue_key":"i_lesson","locale":"he","line_order":0,"content":"קום! קום! כל העמק קפוא! ומירה... מירה תקועה בתוך גוש קרח!","line_format":"plain_text"},{"dialogue_key":"i_turnin","locale":"he","line_order":0,"content":"ברררר... כמה זמן הייתי שם?","line_format":"plain_text"},{"dialogue_key":"intro1_turnin","locale":"he","line_order":0,"content":"שמעת? הבאר ענתה לך! היא לא עונה לכל אחד.","line_format":"plain_text"},{"dialogue_key":"intro1_wake","locale":"he","line_order":0,"content":"חררר... מה? מי שם?! אה! סליחה, רק עצמתי את העיניים לרגע.","line_format":"plain_text"},{"dialogue_key":"intro2_bruno","locale":"he","line_order":0,"content":"אה, שלום לך! סליחה, לא שמתי לב שבאת. הנה, קח תפוח. טרי מהעץ!","line_format":"plain_text"},{"dialogue_key":"intro2_mira","locale":"he","line_order":0,"content":"שלום! אתה החדש? בוא, תתקרב. העיניים שלי כבר לא משהו, אבל הידיים שלי זוכרות הכול.","line_format":"plain_text"},{"dialogue_key":"intro2_noa","locale":"he","line_order":0,"content":"בו! נבהלת? חה! אני נועה. ראיתי אותך מסתובב פה כל היום.","line_format":"plain_text"},{"dialogue_key":"intro2_pip","locale":"he","line_order":0,"content":"היי! כאן! שמעת את הפעמון? דונג... ככה הוא נשמע היום. עמום ועצוב.","line_format":"plain_text"},{"dialogue_key":"intro2_turnin","locale":"he","line_order":0,"content":"נו, הכרת את כולם? מירה שכמעט לא רואה, פיפ והפעמון שאיבד את הצלילים, ברונו והזרעים הישנים...","line_format":"plain_text"},{"dialogue_key":"intro3_story","locale":"he","line_order":0,"content":"תקשיבו כולם. הגיע הזמן שתדעו את האמת.","line_format":"plain_text"},{"dialogue_key":"intro3_turnin","locale":"he","line_order":0,"content":"זה היה הוא. הקוסם האפל. הוא חזר.","line_format":"plain_text"},{"dialogue_key":"j_lesson","locale":"he","line_order":0,"content":"הצנצנות שלי! הקוסם כישף אותן, והן קפצו מהמדף! ואני צריך אותן לפסטיבל הריבה!","line_format":"plain_text"},{"dialogue_key":"j_turnin","locale":"he","line_order":0,"content":"כל הצנצנות! גם זאת עם הריבה של סבתא!","line_format":"plain_text"},{"dialogue_key":"k_lesson","locale":"he","line_order":0,"content":"הקוסם נעל את שלושת הבתים! והמפתחות מוסתרים בתיבות בכפר.","line_format":"plain_text"},{"dialogue_key":"k_turnin","locale":"he","line_order":0,"content":"הדלת שלי נפתחה! והעפיפון שלך... עוד בשמיים?","line_format":"plain_text"},{"dialogue_key":"l_lesson","locale":"he","line_order":0,"content":"הקוסם גנב את כל האור של הלילה, והגחליליות ברחו. יש לי רעיון: נתפוס אותן בצנצנות!","line_format":"plain_text"},{"dialogue_key":"l_turnin","locale":"he","line_order":0,"content":"פעם פחדתי מהחושך. עכשיו... קצת פחות.","line_format":"plain_text"},{"dialogue_key":"m_lesson","locale":"he","line_order":0,"content":"אני מתחיל להיזכר בימים שבהם האותיות זהרו. אבל הכול מטושטש...","line_format":"plain_text"},{"dialogue_key":"m_turnin","locale":"he","line_order":0,"content":"פסל, צלילים, ציור... כן. כן! נזכרתי.","line_format":"plain_text"},{"dialogue_key":"n_lesson","locale":"he","line_order":0,"content":"אחרי כל ההרפתקאות מגיעה לכפר ארוחה! אבל הקוסם כישף את המטבח, וכל המצרכים ברחו לבתים של השכנים.","line_format":"plain_text"},{"dialogue_key":"n_turnin","locale":"he","line_order":0,"content":"עוד צלחת? כמובן! N כמו noodles, ו-N כמו never enough noodles.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
